import {chapters,equipment,sources} from './content.js';
import {createWorld} from './world.js';
let current=0,currentEquipment=null,activeFlow=null,scrollFrame=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const nav=document.querySelector('#chapters'),copy=document.querySelector('#chapter-copy'),detail=document.querySelector('#equipment-dialog'),detailContent=document.querySelector('#equipment-content');
const world=createWorld(document.querySelector('#world'),select);
const names=['The beginning','Electricity','Computation','Heat','Connection','People'];
const titles=['The cloud is a place.','Nothing happens<br>without power.','A world of work.<br>Inside a box.','The work stays.<br>The heat leaves.','A conversation<br>between machines.','It doesn’t run<br>itself.'];
const leads=['A journey through the machines, energy, and people behind every click.','Before a single bit moves, electricity travels through transformers, backup systems, and distribution equipment.','Rows of racks hold the computers. Inside each one: processors, memory, storage, and a connection to the world.','Computing turns electricity into heat. Air and liquid carry it out of the servers and back to the environment.','Fiber, switches, and network interfaces connect the servers to each other and the facility to the outside world.','People monitor conditions, maintain the machines, control access, and respond when something goes wrong.'];
const captions={power:'UTILITY → TRANSFORMER → UPS → DISTRIBUTION → SERVER',cooling:'RED: HEAT TRANSFER · BLUE: COOLANT RETURN',network:'FIBER → SWITCHES → RACK → SERVER'};
nav.innerHTML=names.map((name,i)=>`<button data-chapter="${i}"><span>${String(i+1).padStart(2,'0')}</span>${name}</button>`).join('');
nav.addEventListener('click',e=>{const b=e.target.closest('[data-chapter]');if(b)go(Number(b.dataset.chapter));});
function render(){
 const c=chapters[current];document.documentElement.style.setProperty('--accent',c.color);document.body.dataset.chapter=c.id;
 nav.querySelectorAll('button').forEach((b,i)=>{if(i===current)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});
 document.querySelector('#chapter-count').textContent=String(current+1).padStart(2,'0')+' / 06';document.querySelector('#previous').disabled=current===0;document.querySelector('#next').disabled=current===5;
 const flow=['power','cooling','network'].includes(c.id)?c.id:null;
 copy.innerHTML=`<p class="eyebrow">${current===0?'A JOURNEY INSIDE':String(current+1).padStart(2,'0')+' / '+names[current].toUpperCase()}</p><${current===0?'h1':'h2'}>${titles[current]}</${current===0?'h1':'h2'}><p class="lead">${leads[current]}</p>${current===0?'<button class="enter-button" id="enter">Explore the datacenter <span aria-hidden="true">↓</span></button><p class="page-scroll-hint">SCROLL TO TRAVEL THROUGH THE WORLD</p>':`<div class="chapter-actions"><button id="open-guide">${current===2?'Open a server':'Explore the equipment'} ↗</button>${flow?`<button id="trace" aria-pressed="${activeFlow===flow}">${activeFlow===flow?'Hide':'Follow'} the ${flow==='cooling'?'heat':flow==='network'?'data':'power'}</button>`:''}</div><p class="flow-caption" aria-live="polite">${activeFlow?captions[activeFlow]:''}</p>`}`;
 document.querySelector('#enter')?.addEventListener('click',()=>go(1));
 document.querySelector('#open-guide')?.addEventListener('click',()=>current===2?select('server'):openGuide());
 document.querySelector('#trace')?.addEventListener('click',()=>setFlow(activeFlow===flow?null:flow));
}
function closeDetail(){if(detail.open)detail.close();currentEquipment=null;world.clearFocus();}
function go(i){i=Math.max(0,Math.min(5,i));closeDetail();nav.classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:(document.documentElement.scrollHeight-innerHeight)*i/5,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function onScroll(){scrollFrame=0;const progress=Math.max(0,Math.min(5,window.scrollY/(document.documentElement.scrollHeight-innerHeight)*5));world.journey(progress);document.querySelector('#progress-fill').style.height=progress/5*100+'%';const next=Math.min(5,Math.round(progress));if(next!==current){current=next;activeFlow=null;world.flow(null);render();}}
window.addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(onScroll);},{passive:true});window.addEventListener('resize',onScroll);
function openGuide(){detailContent.innerHTML=`<p class="eyebrow">${names[current].toUpperCase()}</p><h2>Look closer.</h2><p>${chapters[current].lead}</p><div class="equipment-list">${chapters[current].items.map(id=>`<button data-equipment="${id}">${equipment[id]?.name||chapters.find(c=>c.id===id)?.name}<span>↗</span></button>`).join('')}</div><p class="detail-insight">${chapters[current].fact}</p>`;detailContent.querySelectorAll('[data-equipment]').forEach(b=>b.onclick=()=>select(b.dataset.equipment));if(!detail.open)detail.showModal();}
function select(id){if(!equipment[id]){const i=chapters.findIndex(c=>c.id===id);if(i>=0)go(i);return;}const e=equipment[id];currentEquipment=id;activeFlow=null;world.flow(null);world.select(id);detailContent.innerHTML=`<button class="back-equipment">← Equipment guide</button><p class="eyebrow">${e.chapter.toUpperCase()} / LOOK CLOSER</p><h2 tabindex="-1">${e.name}</h2><p>${e.description}</p><p class="equipment-path">${e.path}</p><p class="eyebrow">WHY IT MATTERS</p><p class="detail-insight">${e.insight}</p>${['server','cpu','gpu','memory','storage','nic'].includes(id)?`<div class="equipment-list">${['cpu','gpu','memory','storage','nic'].filter(k=>k!==id).map(k=>`<button data-equipment="${k}">${equipment[k].name}<span>↗</span></button>`).join('')}</div>`:''}${e.source?`<a class="source-link" href="${e.source}" target="_blank" rel="noreferrer">Read the source ↗</a>`:''}`;detailContent.querySelector('.back-equipment').onclick=()=>{currentEquipment=null;world.clearFocus();openGuide();};detailContent.querySelectorAll('[data-equipment]').forEach(b=>b.onclick=()=>select(b.dataset.equipment));if(!detail.open)detail.showModal();detailContent.querySelector('h2').focus({preventScroll:true});}
function setFlow(id){activeFlow=id;world.flow(id);render();}
const motion=document.querySelector('#motion-button');function updateMotion(){motion.textContent=paused?'Motion off':'Motion on';motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Play ambient animation':'Pause ambient animation');world.pause(paused);}motion.onclick=()=>{paused=!paused;updateMotion();};
for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)dialog.close();}});}
detail.addEventListener('close',()=>{if(detail.open)return;currentEquipment=null;world.clearFocus();document.querySelector('#open-guide')?.focus({preventScroll:true});});
document.querySelector('#about-button').onclick=()=>document.querySelector('#about-dialog').showModal();document.querySelector('#home').onclick=()=>go(0);document.querySelector('#previous').onclick=()=>go(current-1);document.querySelector('#next').onclick=()=>go(current+1);document.querySelector('#reset-view').onclick=()=>world.reset();document.querySelector('#menu-toggle').onclick=()=>{const open=nav.classList.toggle('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));};
document.querySelector('#source-list').innerHTML='<p class="eyebrow">FURTHER READING</p>'+sources.map(s=>`<p><a href="${s.url}" target="_blank" rel="noreferrer">${s.title} ↗</a></p>`).join('');
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey)return;if(/^[1-6]$/.test(e.key)){go(Number(e.key)-1);e.preventDefault();}if(['ArrowDown','ArrowRight'].includes(e.key)){go(current+1);e.preventDefault();}if(['ArrowUp','ArrowLeft'].includes(e.key)){go(current-1);e.preventDefault();}});
render();updateMotion();onScroll();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'explore_datacenter',title:'Explore the datacenter',description:'Travel to a datacenter chapter, inspect equipment, or trace power, heat, and data in the visible world.',inputSchema:{type:'object',properties:{chapter:{type:'string',enum:chapters.map(c=>c.id)},equipment:{type:'string',enum:Object.keys(equipment)},flow:{type:'string',enum:['power','cooling','network','none']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['chapter','equipment','flow'].includes(k)))throw Error('Invalid options');if(input.chapter!==undefined&&!chapters.some(c=>c.id===input.chapter))throw Error('Unknown chapter');if(input.equipment!==undefined&&!Object.hasOwn(equipment,input.equipment))throw Error('Unknown equipment');if(input.flow!==undefined&&!['power','cooling','network','none'].includes(input.flow))throw Error('Unknown flow');if(input.chapter&&input.equipment&&equipment[input.equipment].chapter!==input.chapter)throw Error('Equipment does not belong to this chapter');if(input.equipment&&input.flow&&input.flow!=='none')throw Error('Choose equipment or a flow');if(input.chapter){closeDetail();current=chapters.findIndex(c=>c.id===input.chapter);window.scrollTo({top:(document.documentElement.scrollHeight-innerHeight)*current/5,behavior:'instant'});onScroll();render();}if(input.equipment)select(input.equipment);if(input.flow!==undefined)setFlow(input.flow==='none'?null:input.flow);return{chapter:chapters[current].id,equipment:currentEquipment,flow:activeFlow,title:currentEquipment?equipment[currentEquipment].name:names[current],graphicsAvailable:!!document.querySelector('#world canvas')};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
